import sys,random
def run(path):
    t=open(path).read().split(); w,h,s=map(int,t[:3]); g=[int(x) for x in t[3:3+w*h]]
    for _ in range(s):
        n=[0]*(w*h)
        for y in range(h):
            for x in range(w):
                i=y*w+x
                l=g[i-1] if x>0 else g[i]; r=g[i+1] if x<w-1 else g[i]
                u=g[i-w] if y>0 else g[i]; d=g[i+w] if y<h-1 else g[i]
                n[i]=(4*g[i]+l+r+u+d)//8
        g=n
    out=[" ".join(str(v) for v in g[y*w:(y+1)*w]) for y in range(h)]
    return "\n".join(out)+f"\nSUM {sum(g)}\n"
if sys.argv[1]=="gen":
    w,h,s,seed=map(int,sys.argv[2:6]); random.seed(seed)
    print(w,h,s)
    for y in range(h): print(" ".join(str(random.randint(0,1000000)) for _ in range(w)))
else: sys.stdout.write(run(sys.argv[2]))
EOF

